<script setup lang="ts">
import { onMounted, ref } from 'vue'
import AppLayout from '../../components/layout/AppLayout.vue'
import BaseCard from '../../components/ui/BaseCard.vue'
import { financeService } from '../../services/finance/service'
import type { Caisse, Paiement } from '../../models/finance/model'
import { userError } from '../../utils/errors'
const caisses = ref<Caisse[]>([]); const payments = ref<Paiement[]>([]); const gareId = ref(''); const ouverture = ref('0'); const reservationId = ref(''); const caisseId = ref(''); const montant = ref(''); const busy = ref(false); const loading = ref(true); const error = ref(''); const success = ref('')
function showError(value: unknown, fallback = 'Opération financière impossible.') { error.value = userError(value, fallback, 'FINANCE_ERROR'); success.value = '' }
async function load() { loading.value = true; try { const [cash, paid] = await Promise.all([financeService.caisses({ page: 1, page_size: 50 }), financeService.payments({ page: 1, page_size: 50 })]); caisses.value = cash.items; payments.value = paid.items } catch (value: unknown) { showError(value, 'Impossible de charger la caisse.') } finally { loading.value = false } }
async function open() { busy.value = true; try { await financeService.open({ id_gare: Number(gareId.value), montant_ouverture: Number(ouverture.value) }); success.value = 'Caisse ouverte.'; await load() } catch (value: unknown) { showError(value) } finally { busy.value = false } }
async function close(item: Caisse) { if (!window.confirm('Clôturer cette caisse ?')) return; busy.value = true; try { await financeService.close(item.id); success.value = 'Caisse clôturée.'; await load() } catch (value: unknown) { showError(value) } finally { busy.value = false } }
async function pay() { busy.value = true; try { await financeService.pay({ id_reservation: Number(reservationId.value), id_caisse: Number(caisseId.value), montant: Number(montant.value) }); success.value = 'Paiement en espèces enregistré.'; await load() } catch (value: unknown) { showError(value) } finally { busy.value = false } }
onMounted(load)
</script>
<template><AppLayout><template #title>Paiements & caisse</template><div class="page-intro"><div><p class="eyebrow">FINANCES</p><h2>Paiements & caisse</h2><p>Le paiement actuellement disponible est le paiement à la gare en espèces.</p></div></div><p v-if="error" class="error-banner">{{ error }}</p><p v-if="success" class="success-banner">{{ success }}</p><section class="content-grid"><BaseCard><div class="card-heading"><div><h2>Ouvrir une caisse</h2><p>Une seule caisse ouverte par gare.</p></div></div><div class="form-grid"><label class="form-field"><span>ID gare *</span><input v-model="gareId" type="number" min="1" /></label><label class="form-field"><span>Montant d’ouverture</span><input v-model="ouverture" type="number" min="0" step="0.01" /></label></div><button class="primary-button" :disabled="busy || !gareId" @click="open">Ouvrir</button></BaseCard><BaseCard><div class="card-heading"><div><h2>Encaisser une réservation</h2><p>Réservation confirmée, paiement exact du solde.</p></div></div><div class="form-grid"><label class="form-field"><span>ID réservation *</span><input v-model="reservationId" type="number" min="1" /></label><label class="form-field"><span>ID caisse *</span><input v-model="caisseId" type="number" min="1" /></label><label class="form-field"><span>Montant *</span><input v-model="montant" type="number" min="0.01" step="0.01" /></label></div><button class="primary-button" :disabled="busy || !reservationId || !caisseId || !montant" @click="pay">Enregistrer le paiement</button></BaseCard></section><BaseCard><div class="card-heading"><div><h2>Historique des caisses</h2><p>Ouvertures, clôtures et soldes calculés à partir des opérations.</p></div></div><p v-if="loading" class="status-msg">Chargement…</p><div v-else class="table-scroll"><table class="data-table"><thead><tr><th>Gare</th><th>Ouverture</th><th>Recettes</th><th>Dépenses</th><th>Solde</th><th>Statut</th><th>Action</th></tr></thead><tbody><tr v-for="item in caisses" :key="item.id"><td>#{{ item.id_gare }}</td><td>{{ item.montant_ouverture }}</td><td>{{ item.total_recettes }}</td><td>{{ item.total_depenses }}</td><td>{{ item.solde }}</td><td>{{ item.statut }}</td><td><button v-if="item.statut === 'OUVERTE'" class="table-action danger-action" :disabled="busy" @click="close(item)">Clôturer</button></td></tr><tr v-if="!caisses.length"><td colspan="7" class="empty-state">Aucune caisse.</td></tr></tbody></table></div></BaseCard><BaseCard><div class="card-heading"><div><h2>Paiements récents</h2></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Réservation</th><th>Montant</th><th>Méthode</th><th>Référence</th><th>Statut</th></tr></thead><tbody><tr v-for="item in payments" :key="item.id"><td>#{{ item.id_reservation }}</td><td>{{ item.montant }}</td><td>{{ item.methode }}</td><td>{{ item.reference_paiement || '—' }}</td><td>{{ item.statut }}</td></tr><tr v-if="!payments.length"><td colspan="5" class="empty-state">Aucun paiement.</td></tr></tbody></table></div></BaseCard></AppLayout></template>
